import { create } from "zustand";

// /assets/manifest.json lists every file in public/assets (generated by the Vite plugin in dev and at build).
// When it exists, only listed files are requested, so missing assets never cause 404s.
// If it can't be loaded, `useAsset` returns the path and <SmartImg> falls back on error.
interface M { files: Set<string> | null; loaded: boolean }
export const useManifest = create<M>(() => ({ files: null, loaded: false }));

let done: () => void = () => {};
export const manifestReady = new Promise<void>((r) => (done = r));

export async function loadManifest() {
  try {
    const r = await fetch(import.meta.env.BASE_URL + "assets/manifest.json", { cache: "no-cache" });
    if (r.ok && (r.headers.get("content-type") ?? "").includes("json")) {
      const j = await r.json();
      useManifest.setState({ files: new Set<string>(j.files), loaded: true });
    } else useManifest.setState({ loaded: true });
  } catch { useManifest.setState({ loaded: true }); }
  done();
}

/** Returns the path if the asset should be requested, otherwise null (use the placeholder). */
export function useAsset(path: string | null | undefined, strict = false): string | null {
  const { files, loaded } = useManifest();
  if (!path || !loaded) return null;
  if (files) return files.has(path) ? path : null;
  return strict ? null : path;
}

export async function assetKnown(path: string): Promise<boolean> {
  await manifestReady;
  const { files } = useManifest.getState();
  return files ? files.has(path) : true;
}
